import java.io.*;
import java.util.*;

public class I {

    public static boolean DEBUG = true;
    public static String name = "I";

    public static void main(String[] args) throws IOException {
        Scanner scan;
        PrintWriter out;
        if (DEBUG) {
            scan = new Scanner(System.in);
            out = new PrintWriter(System.out);
        } else {
            scan = new Scanner(new File(name + ".in"));
            out = new PrintWriter(new BufferedWriter(new FileWriter(name + ".out")));
        }

        float N = Float.parseFloat(scan.next());
        float P = Float.parseFloat(scan.next());

        for (int i = 0; i <= N; i++) {
            double comb3_i = i * (i - 1) * (i - 2) / 6.0;
            double comb2_i_1_N = i * (i - 1) * (N - i) / 2.0;
            double comb1_i_2_N = i * (N - i) * (N - i - 1) / 4.0;
            double numerator = comb3_i + comb2_i_1_N + comb1_i_2_N;
            double denominator = N * (N - 1) * (N - 2) / 6.0;
            double val = numerator / denominator;

            if (val >= P) {
                out.println(i);
                break;
            }
        }

        out.close();
        scan.close();
    }
}
